const $=id=>document.getElementById(id);let state=initialState();let language=document.documentElement.lang==='en'?'en':'zh-Hant';let initialized=false;const t=k=>COPY[language][k];
function el(tag,text){const e=document.createElement(tag);if(text!==undefined)e.textContent=text;return e;}
function svg(tag,attrs={},text){const e=document.createElementNS('http://www.w3.org/2000/svg',tag);for(const [k,v]of Object.entries(attrs))e.setAttribute(k,String(v));if(text!==undefined)e.textContent=text;return e;}
const number=r=>Number(r.n)/Number(r.d),x=r=>80+840*number(r),y=r=>520-440*number(r);
function draw(result){const chart=$('chart');chart.replaceChildren();chart.setAttribute('aria-label',t('graph'));chart.append(svg('title',{},t('graph')));chart.append(svg('path',{d:'M80 80V520H920',fill:'none',stroke:'#42566c','stroke-width':2}));for(const [xx,yy,text]of [[65,548,'0'],[915,548,'1'],[50,85,'1']])chart.append(svg('text',{x:xx,y:yy,fill:'#172b3f','font-size':20},text));
 for(const seg of result.segments)chart.append(svg('line',{x1:x(seg.left),x2:x(seg.right),y1:y(seg.y),y2:y(seg.y),stroke:'#154f86','stroke-width':4}));
 for(const row of result.rows){const xx=x(row.p),a=y(row.before),b=y(row.after),same=a===b;if(!same){chart.append(svg('line',{x1:xx,x2:xx,y1:a,y2:b,stroke:'#627489','stroke-width':2,'stroke-dasharray':'5 5'}));chart.append(svg('polygon',{points:`${xx},${a-6} ${xx+6},${a} ${xx},${a+6} ${xx-6},${a}`,fill:'#fff',stroke:'#663590','stroke-width':2}));}chart.append(svg('circle',{cx:xx,cy:b,r:4.5,fill:'#154f86',stroke:'#fff','stroke-width':1}));if(same)chart.append(svg('text',{x:xx+8,y:b-10,fill:'#172b3f','font-size':15},t('same')));}
 chart.append(svg('line',{x1:x(result.p),x2:x(result.p),y1:75,y2:520,stroke:'#a32132','stroke-width':1.5,'stroke-dasharray':'3 5'}));chart.append(svg('circle',{cx:x(result.p),cy:y(result.y),r:9,fill:'none',stroke:'#a32132','stroke-width':3}));chart.append(svg('text',{x:80,y:585,fill:'#42566c','font-size':18},`${t('unitBoundary')} · p=0`));
 const tracks=$('tracks');tracks.replaceChildren();for(const [name,r,color]of [[t('linear'),result.p,'#154f86'],[t('eased'),result.y,'#663590']]){tracks.append(el('p',`${name}: ${fraction(r)} (${percentage(r)} ${t('rounded')})`));const s=svg('svg',{viewBox:'0 0 1000 55',width:'100%',height:40,role:'img','aria-label':`${name}: ${fraction(r)}`});s.append(svg('line',{x1:20,y1:25,x2:980,y2:25,stroke:'#627489','stroke-width':2}));const cx=30+940*number(r);if(name===t('linear'))s.append(svg('circle',{cx,cy:25,r:9,fill:color}));else s.append(svg('polygon',{points:`${cx},15 ${cx+10},25 ${cx},35 ${cx-10},25`,fill:color}));s.append(svg('text',{x:10,y:54,fill:'#42566c','font-size':16},'0%'));s.append(svg('text',{x:946,y:54,fill:'#42566c','font-size':16},'100%'));tracks.append(s);}
}
// 語言切換只重繪，不重新解析 dirty 值或更換計算結果。
function render(){
 for(const key of ['N','position','mode','progress'])if($(key).value!==state.raw[key])$(key).value=state.raw[key];$('before').checked=state.raw.before;
 $('decimal-wrap').hidden=state.raw.mode!=='decimal';$('boundary-wrap').hidden=state.raw.mode!=='boundary';const k=$('k');if(state.builtN===null){k.replaceChildren();k.disabled=true;}else{if(k.options.length!==state.builtN+1){k.replaceChildren();for(let i=0;i<=state.builtN;i++){const o=el('option',`${i}/${state.builtN}`);o.value=String(i);k.append(o);}}k.disabled=false;k.value=String(state.k);}
 for(const id of ['N','position','mode','progress','k','before']){$(`${id}-error`).textContent='';$(id).setAttribute('aria-invalid','false');}
 for(const error of state.errors){const id=error.field;$(`${id}-error`).textContent=COPY.errors[language][error.code]??COPY.errors[language].schema;$(id).setAttribute('aria-invalid','true');}
 $('error-summary').textContent=state.errors.length?`${t('errorStatus')} (${state.errors.length})`:'';
 $('status').textContent=t(state.phase==='error'?'errorStatus':state.phase);
 const r=state.result;$('result').hidden=!r;$('placeholder').hidden=!!r;$('select-css').disabled=!r;$('css').value=r?r.css:'';
 if(!r){$('table-body').replaceChildren();$('chart').replaceChildren();$('metrics').replaceChildren();$('tracks').replaceChildren();$('trace').textContent='';return;}
 $('metrics').replaceChildren();for(const [label,value] of [[t('inputValue'),r.p],[t('outputValue'),r.y]]){const c=el('div');c.className='metric';c.append(el('span',label),el('strong',fraction(value)),el('span',`${percentage(value)} · ${t('rounded')}`));$('metrics').append(c);}
 $('trace').textContent=`${t('trace')}: h=${r.h}, c=${r.c}, J=${r.J} · ${r.position} · ${r.mode==='boundary'?`${t('boundaryUsed')} ${r.k}/${r.N}`:t('decimal')} · before=${r.before}`;
 $('caption').textContent=`${t('table')} · ${r.rows.length} ${t('rows')}`;const fragment=document.createDocumentFragment();for(const row of r.rows){const tr=el('tr');for(const value of [fraction(row.p),`${fraction(row.before)} · ${percentage(row.before)}`,`${fraction(row.after)} · ${percentage(row.after)}`,t(fraction(row.before)===fraction(row.after)?'same':'different')])tr.append(el('td',value));fragment.append(tr);}$('table-body').replaceChildren(fragment);draw(r);
}
function dispatch(action){const focused=document.activeElement;if((action.type==='edit'||action.type==='suspend'||action.type==='compose')&&$('result').contains(focused))$('generate').focus();state=transition(state,action);render();}
function locale(){for(const node of document.querySelectorAll('[data-i18n]')){const text=t(node.dataset.i18n);if(text!==undefined)node.textContent=text;}document.querySelector('a[data-i18n=alternate]').setAttribute('href',language==='en'?'/index.html':'/en/index.html');document.documentElement.lang=language;document.title=`${t('title')} · GlossQuote`;document.querySelector('meta[name=description]').setAttribute('content',t('description'));$('home').href=`https://glossquote.com/${language==='en'?'en/':''}index.html`;$('home').setAttribute('aria-label',t('home'));$('graph-scroll').setAttribute('aria-label',t('graph'));$('table-scroll').setAttribute('aria-label',t('table'));}
try{
 if(typeof BigInt!=='function'||!document.createElementNS('http://www.w3.org/2000/svg','svg').createSVGRect)throw Error('unsupported');
 for(const id of ['N','progress']){const input=$(id);input.addEventListener('input',()=>dispatch({type:'edit',field:id,value:input.value}));input.addEventListener('compositionstart',()=>dispatch({type:'compose',value:true}));input.addEventListener('compositionend',()=>dispatch({type:'compose',value:false}));}
 for(const id of ['position','mode'])$(id).addEventListener('change',()=>dispatch({type:'edit',field:id,value:$(id).value}));$('before').addEventListener('change',()=>dispatch({type:'edit',field:'before',value:$('before').checked}));$('k').addEventListener('change',()=>dispatch({type:'boundary',value:Number($('k').value)}));
 $('form').addEventListener('keydown',e=>{if(e.key==='Enter'&&(e.isComposing||state.composing))e.preventDefault();});$('form').addEventListener('submit',e=>{e.preventDefault();if(state.composing)return;dispatch({type:'generate'});if(state.errors.length)$(state.errors[0].field).focus();});
 $('reset').addEventListener('click',()=>{dispatch({type:'reset'});$('N').focus();});$('example-default').addEventListener('click',()=>dispatch({type:'example',name:'defaults'}));$('example-both').addEventListener('click',()=>dispatch({type:'example',name:'both'}));
 $('locale').addEventListener('click',()=>{const focus=document.activeElement;language=language==='en'?'zh-Hant':'en';locale();render();focus?.focus();});
 $('select-css').addEventListener('click',()=>{if(!state.result)return;try{$('css').focus();$('css').select();$('status').textContent=t('selected');}catch{$('status').textContent=t('selectFallback');}});
 document.addEventListener('visibilitychange',()=>{if(document.hidden)dispatch({type:'suspend'});});window.addEventListener('pagehide',()=>dispatch({type:'suspend'}));window.addEventListener('pageshow',e=>{if(e.persisted)dispatch({type:'suspend'});});
 for(const c of document.querySelectorAll('button,input,select'))c.disabled=false;initialized=true;locale();render();
}catch{for(const c of document.querySelectorAll('button,input,select'))c.disabled=true;$('status').textContent=t('unsupported');$('result').hidden=true;$('css').value='';}
